CREATE TABLE manual_journal(tenant_id uuid NOT NULL,company_id uuid NOT NULL,branch_id uuid NOT NULL,id uuid NOT NULL,business_date date NOT NULL,status text NOT NULL CHECK(status IN('DRAFT','IN_REVIEW','REJECTED','POSTED')),reason text NOT NULL,created_by uuid NOT NULL,submitted_by uuid,approved_by uuid,reversal_of uuid,journal_id uuid,version bigint NOT NULL DEFAULT 0,PRIMARY KEY(tenant_id,company_id,id),UNIQUE(tenant_id,company_id,reversal_of),FOREIGN KEY(tenant_id,company_id,reversal_of)REFERENCES manual_journal(tenant_id,company_id,id),FOREIGN KEY(tenant_id,company_id,journal_id)REFERENCES journal_entry(tenant_id,company_id,id),FOREIGN KEY(tenant_id,company_id,branch_id)REFERENCES branch(tenant_id,company_id,id),CHECK(status<>'POSTED' OR(journal_id IS NOT NULL AND approved_by IS NOT NULL AND submitted_by IS NOT NULL AND approved_by<>submitted_by AND approved_by<>created_by)));
CREATE TABLE manual_journal_line(tenant_id uuid NOT NULL,company_id uuid NOT NULL,branch_id uuid NOT NULL,id uuid NOT NULL,manual_id uuid NOT NULL,account text NOT NULL,debit_xaf bigint NOT NULL CHECK(debit_xaf>=0),credit_xaf bigint NOT NULL CHECK(credit_xaf>=0),PRIMARY KEY(tenant_id,company_id,id),FOREIGN KEY(tenant_id,company_id,manual_id)REFERENCES manual_journal(tenant_id,company_id,id),CHECK((debit_xaf>0 AND credit_xaf=0)OR(credit_xaf>0 AND debit_xaf=0)));
DO $$ DECLARE t text;BEGIN FOREACH t IN ARRAY ARRAY['manual_journal','manual_journal_line']LOOP EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY',t);EXECUTE format('ALTER TABLE %I FORCE ROW LEVEL SECURITY',t);EXECUTE format('CREATE POLICY scope_isolation ON %I USING(tenant_id=app_tenant() AND company_id=app_company() AND branch_id=app_branch())WITH CHECK(tenant_id=app_tenant() AND company_id=app_company() AND branch_id=app_branch())',t);END LOOP;END$$;
GRANT SELECT,INSERT,UPDATE ON manual_journal TO quincai_app;GRANT SELECT,INSERT ON manual_journal_line TO quincai_app;
CREATE TRIGGER manual_lines_immutable BEFORE UPDATE OR DELETE ON manual_journal_line FOR EACH ROW EXECUTE FUNCTION reject_fact_mutation();
CREATE FUNCTION protect_manual_journal()RETURNS trigger LANGUAGE plpgsql AS $$BEGIN IF OLD.status='POSTED' THEN RAISE EXCEPTION 'Posted manual journal immutable';END IF;IF NEW.business_date<>OLD.business_date OR NEW.created_by<>OLD.created_by OR NEW.reversal_of IS DISTINCT FROM OLD.reversal_of THEN RAISE EXCEPTION 'Manual journal source immutable';END IF;RETURN NEW;END$$;
CREATE TRIGGER manual_journal_immutable BEFORE UPDATE ON manual_journal FOR EACH ROW EXECUTE FUNCTION protect_manual_journal();
CREATE FUNCTION protect_manual_line_insert()RETURNS trigger LANGUAGE plpgsql AS $$BEGIN IF NOT EXISTS(SELECT FROM manual_journal j WHERE j.tenant_id=NEW.tenant_id AND j.company_id=NEW.company_id AND j.branch_id=NEW.branch_id AND j.id=NEW.manual_id AND j.status='DRAFT')THEN RAISE EXCEPTION 'Draft manual journal required';END IF;RETURN NEW;END$$;
CREATE TRIGGER manual_line_draft BEFORE INSERT ON manual_journal_line FOR EACH ROW EXECUTE FUNCTION protect_manual_line_insert();
